const TRIGGER_FOCUS = "art:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:data-[artemis-pointer-focus]:focus-visible:shadow-none art:data-[artemis-pointer-focus]:focus-visible:ring-0 art:data-[artemis-pointer-focus]:focus-visible:ring-offset-0";
const PREVIEW_FULL_BLEED = "body>main.py-4:has(>main[class~=\"@container/dashboard\"]){padding-top:0;padding-bottom:0;--preview-viewport-height:100svh}";
const NEXT_REPLY_BY_ID = new Map(REQUESTS.map((r, i) => [r.id, ["2h left", "45m left", "1d left", "6h left", "Overdue", "3h left"][i % 6]]));
function reveal(index: number, reduce: boolean | null) {
    return {
        initial: reduce ? false : { opacity: 0, y: 8 },
