}
interface MetricMeta {
    label: string;
    icon: LucideIcon;
    unit?: string;
    key: keyof PeriodData["kpis"];
}
const METRICS: MetricMeta[] = [
    { label: "New requests", icon: Inbox, key: "requests" },
