    { label: "Reply targets met", icon: CheckCheck, key: "targets" },
    { label: "Customer rating", icon: ThumbsUp, unit: "/ 5", key: "rating" },
];
function MetricCard({ meta, value, delta, tone }: {
    meta: MetricMeta;
    value: string;
    delta: string | null;
