}) {
    const Icon = meta.icon;
    const positive = delta?.startsWith("+") ?? false;
    return (<div className="art:@container/metric art:flex art:min-w-0 art:flex-col art:justify-between art:bg-background art:p-4 art:@lg:flex-1 art:gap-5 art:@lg:min-w-56">
