        </motion.div>
        <motion.div className="art:grid art:min-w-0 art:items-start art:gap-5 art:@5xl/dashboard:grid-cols-[minmax(0,2.2fr)_minmax(320px,1fr)]" {...reveal(2, reduce)}>
