        </motion.div>
        <motion.div {...reveal(3, reduce)}>
          <ResponseQueue titleId={`${id}-queue`} requests={inPeriod} actions={actions}/>
        </motion.div>
        <footer className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-2 art:text-xs art:text-muted-foreground">
          <span>
            {"Demo inbox \u00B7 "}
            {"Data as of"} {"Sep 30, 11:30 AM"}
            {" UTC"}
          </span>
          <p aria-live="polite" className="art:min-h-4">
            {notice}
          </p>
        </footer>
      </div>
      <RequestDialog open={dialogOpen} request={dialogRequest} onClose={() => setDialogOpen(false)} onToggleClosed={(request) => actions.toggleClosed(request)}/>
    </main>);
}

