interface Totals {
    opened: number;
    closed: number;
    firstReply: number;
    targets: number;
    rating: number;
}
function totals(first: number, last: number): Totals {
    let opened = 0;
    let closed = 0;
    let met = 0;
    let replyWeighted = 0;
    let ratingCount = 0;
    let ratingWeighted = 0;
    for (let i = first; i <= last; i++) {
        const c = DAILY_CLOSED[i];
        const rated = Math.round(c * 0.26);
        opened += DAILY_OPENED[i];
        closed += c;
        met += DAILY_MET[i];
        replyWeighted += (18 + (i % 9)) * c;
        ratingCount += rated;
        ratingWeighted += RATINGS[i % 4] * rated;
    }
    return {
        opened,
        closed,
        firstReply: replyWeighted / closed,
        targets: (met / closed) * 100,
        rating: ratingWeighted / ratingCount,
    };
}
function change(current: number, previous: number | null, higherIsBetter: boolean): Pick<Kpi, "delta" | "tone"> {
    if (previous === null)
        return { delta: null, tone: "flat" };
    const pct = ((current - previous) / previous) * 100;
    if (pct === 0)
        return { delta: "0", tone: "flat" };
    const size = Math.abs(pct);
    const delta = `${pct > 0 ? "+" : "-"}${Number.isInteger(size) ? String(size) : size.toFixed(1)}`;
    return { delta, tone: pct > 0 === higherIsBetter ? "good" : "bad" };
}
const cache = new Map<string, PeriodData>();
export function periodFor(fromIso: string, toIso: string): PeriodData {
    const key = `${fromIso}_${toIso}`;
    const hit = cache.get(key);
    if (hit)
