function StableResponsiveContainer({ children }: {
    children: (size: {
        width: number;
        height: number;
    }) => ReactElement;
}) {
    const ref = useRef<HTMLDivElement>(null);
    const [size, setSize] = useState<{
        width: number;
        height: number;
    } | null>(null);
    useEffect(() => {
        const node = ref.current;
        if (!node)
            return;
        const set = (w: number, h: number) => {
            const width = Math.round(w);
            const height = Math.round(h);
            if (width <= 0 || height <= 0)
                return;
            setSize((prev) => (prev && prev.width === width && prev.height === height ? prev : { width, height }));
        };
        const observer = new ResizeObserver((entries) => {
            const entry = entries[0];
            if (entry)
                set(entry.contentRect.width, entry.contentRect.height);
        });
        const rect = node.getBoundingClientRect();
        set(rect.width, rect.height);
        observer.observe(node);
        return () => observer.disconnect();
    }, []);
    return (<div ref={ref} className="art:recharts-responsive-container" style={{ width: "100%", height: "100%", minWidth: 0 }}>
      <div style={{ width: 0, height: 0, overflow: "visible" }}>{size ? children(size) : null}</div>
    </div>);
}
